vector<int> productExceptSelf(vector<int>& a) {
    int n = a.size();
    vector<int> out(n, 1);
    for (int i = 1; i < n; ++i) out[i] = out[i - 1] * a[i - 1];
    int suf = 1;
    for (int i = n - 1; i >= 0; --i) { out[i] *= suf; suf *= a[i]; }
    return out;
}

public int[] productExceptSelf(int[] a) {
    int n = a.length;
    int[] out = new int[n];
    out[0] = 1;
    for (int i = 1; i < n; i++) out[i] = out[i - 1] * a[i - 1];
    int suf = 1;
    for (int i = n - 1; i >= 0; i--) { out[i] *= suf; suf *= a[i]; }
    return out;
}
